521	    /**
522	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
523	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
524	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
525	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
526	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
527	     * same postcode region, telephone and last name always yield the same customer code.
528	     *
529	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
530	     * @param telephone the owner's normalized (E.164) telephone
531	     * @param lastName  the owner's last name
532	     * @return the formatted customer code
533	     */
534	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
535	        String region = regionForPostcode(postcode);
536	        String hash8 = hashHex(telephone + lastName, 8);
537	        return region + "-" + hash8;
538	    }
