540	    /**
541	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
542	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
543	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
544	     * {@code <REGION>} segment baked into the {@code customerCode}.
545	     *
546	     * @param postcode the owner's postcode, or {@code null}
547	     * @return the region code, or {@code 'UNKNOWN'}
548	     */
549	    private String regionForPostcode(String postcode) {
550	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
551	            return "UNKNOWN";
552	        }
553	        int value = Integer.parseInt(postcode);
554	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
555	            int[] range = entry.getValue();
556	            if (value >= range[0] && value <= range[1]) {
557	                return entry.getKey();
558	            }
559	        }
560	        return "UNKNOWN";
561	    }
