565	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
566	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
567	     * region.
568	     *
569	     * @param city the owner's city
570	     * @return the region code, or {@code 'UNKNOWN'}
571	     */
572	    private String regionForCity(String city) {
573	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
574	    }
