576	    /**
577	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
578	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
579	     * deterministic {@code householdId} (length 12).
580	     *
581	     * @param input  the value to hash
582	     * @param length the number of leading hex characters to return
583	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
584	     */
585	    private String hashHex(String input, int length) {
586	        try {
587	            byte[] digest = MessageDigest.getInstance("SHA-256")
588	                .digest(input.getBytes(StandardCharsets.UTF_8));
589	            StringBuilder hex = new StringBuilder(digest.length * 2);
590	            for (byte b : digest) {
